import{_ as i,l as o,o as e,c as s,v as r,p as l,x as n,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"插值与龙格现象","description":"","frontmatter":{"title":"插值与龙格现象","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interpolation-runge.md","filePath":"cs/interpolation-runge.md","lastUpdated":1789023840000}'),E={name:"cs/interpolation-runge.md"};function c(m,a,A,u,_,f){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="插值与龙格现象" tabindex="-1">插值与龙格现象 <a class="header-anchor" href="#插值与龙格现象" aria-label="Permalink to &quot;插值与龙格现象&quot;">​</a></h1><div class="epigraph"><p>在等距节点上提高多项式次数，并不保证在区间上更接近被插函数；龙格给出了振荡随次数变本加厉的例子。</p><footer>—— 据 Trefethen and Bau, Numerical Linear Algebra；Higham, Accuracy and Stability of Numerical Algorithms 整理</footer></div><p>上一课<a href="/cs/newton-nonlinear">非线性方程与牛顿</a>把求根收成一系列线性系。本课不重讲 Jacobian，也不从逼近论的 Weierstrass 总定理另起。缺口是：多项式能穿过给定点，<strong>穿过节点不等于区间上一致逼近；节点怎么排，本身就是这个映射的条件问题</strong>。本课是数值计算最后一课；下一课改做硅上的<a href="/cs/cmos-inverter">CMOS 反相器</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据 \\((x_i,y_i)\\)，\\(i=0,\\ldots,n\\)，唯一次数 \\(\\le n\\) 的多项式 \\(p\\) 满足 \\(p(x_i)=y_i\\)（节点互异）。这是线性问题：Vandermonde 系统，条件数随等距节点与 \\(n\\) 迅速变坏——上一课的 \\(\\kappa\\) 在此现身。缺口因此不是「插值公式」，而是<strong>插值算子作为 \\(f\\)：节点值映到区间上的函数，可以极病态</strong>。龙格的 \\(1/(1+25x^2)\\) 在 \\([-1,1]\\) 等距节点上，\\(n\\) 增大时两端剧烈振荡。</p><p>Weierstrass 保证连续函数可被某列多项式一致逼近，但那一列不必是等距插值。把「次数更高更准」从泰勒或最小二乘误搬到等距插值，会与龙格直接冲突。换 Chebyshev 节点、换分段、换不经过点的最小二乘，是在换 \\(f\\)，不是把同一 Vandermonde 再多消一次元。</p><h3 id="龙格不是「舍入造成的振荡」" tabindex="-1">龙格不是「舍入造成的振荡」 <a class="header-anchor" href="#龙格不是「舍入造成的振荡」" aria-label="Permalink to &quot;龙格不是「舍入造成的振荡」&quot;">​</a></h3><p>即使精确算术，等距高次插值也可以在节点之间炸掉；这是问题病态，不是 \\(\\gamma_n\\) 没写好。舍入会再叠加——Vandermonde 求解本身就不稳定——但把龙格当成浮点 bug，会去调主元而继续加密等距点。正确动作是换节点族或放弃全局高次多项式。</p><p><span class="marginnote">Trefethen and Bau 用多项式插值连接线性代数与逼近。Higham 讨论 Vandermonde 的恶劣条件。本课不把复分析里的等势线证明写完，只取现象与对策。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点决定基的条件。Chebyshev 节点把极大范数下的 Lebesgue 常数压到对数增长，等距则可以指数坏。分段低次（样条）把问题拆成许多良态小插值。Newton 基比单项式基求值更稳，但不自动消灭龙格——节点仍在。求值用 Horner 时注意求和顺序与抵消。</p>',11)),(e(),l(h,null,{default:n(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E8%8A%82%E7%82%B9%E4%B8%8A%E7%9A%84%E5%80%BC%22%5D%20--%3E%20P%5B%22%E6%AC%A1%E6%95%B0%20n%20%E7%9A%84%E6%8F%92%E5%80%BC%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20EQ%5B%22%E7%AD%89%E8%B7%9D%E8%8A%82%E7%82%B9%22%5D%20--%3E%20RUNGE%5B%22%E5%8C%BA%E9%97%B4%E4%B8%A4%E7%AB%AF%E6%8C%AF%E8%8D%A1%E6%94%BE%E5%A4%A7%22%5D%0A%20%20CH%5B%22Chebyshev%20%E8%8A%82%E7%82%B9%22%5D%20--%3E%20OK%5B%22Lebesgue%20%E5%B8%B8%E6%95%B0%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20P%20--%3E%20RUNGE%0A%20%20P%20--%3E%20OK%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>最小二乘用更低次数去拟合更多点，映射的 \\(\\kappa\\) 通常好得多；它不再保证过点。牛顿求根若用插值模型代替 \\(f\\)，节点选择同样会把模型弄病态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>等距点上的高次振荡，来自基函数为了过点必须在两端用很大的系数对消——又一次近量相消，发生在函数空间而不是两个标量之间。条件数大：节点值的微小扰动（含舍入）在端点附近被放大成巨幅摆动。换节点是在换 \\(f\\) 的采样，使该映射的 \\(\\kappa\\) 下降。数值课到此收束：舍入、条件、稳定、消去、线性与根、插值，都不再碰 IEEE 位型本身。下一课用 CMOS 把比特的物理判决做出来，组成课程开始。</p><p>Lebesgue 常数是插值算子的 \\(\\kappa\\) 在极大范数下的面孔：它给出节点值扰动被放大到区间上的倍数。等距节点上它随 \\(n\\) 指数变坏，Chebyshev 上只对数变坏——同一套「条件数属于问题」的语言。分段样条把 \\(n\\) 换成许多个小的局部 \\(n\\)，每段 \\(\\kappa\\) 可控，代价是整体光滑性要靠连接条件。数值课到此可以交给组成：舍入与条件已经够用来读后课电路里的噪声容限——那是另一类「扰动放大」，对象从矩阵换成电压，但「先问问题敏不敏感」的习惯应当带走。下一课不再做多项式，而做 CMOS 反相器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲有理插值与径向基的全部理论。大模型栏的插值与连续嵌入是另一套对象，本栏不写 Transformer。金融栏的样条定价不进来。后课默认：等距高次插值可以病态；龙格是问题而非纯舍入；组成课从<a href="/cs/cmos-inverter">CMOS 反相器</a>起，不再继续数值分析。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过节点的多项式唯一，但不保证区间上逼近改善。</li><li>龙格：等距高次在精确算术下即可振荡；Vandermonde 还叠加恶劣 \\(\\kappa\\)。</li><li>换 Chebyshev 节点或分段低次，是在换更良态的 \\(f\\)。</li><li>数值计算课结束；下一课是 CMOS 反相器。</li><li>出处：Trefethen and Bau；Higham。</li></ul>',8))])}const g=i(E,[["render",c]]);export{b as __pageData,g as default};
